<script lang="ts">
import { onDestroy } from 'svelte';import {audiosInRange,backend} from './backend.svelte';import {prependTracks} from './player.svelte.ts';import {fmtDur} from './types';import type {Audio,Track} from './types';
let {open=$bindable(false),from=$bindable(''),to=$bindable('')}:{open?:boolean;from?:string;to?:string}=$props();
import {ListMusic,Search,X,Plus,Check} from 'lucide-svelte';
import {createLatestOperation} from './interactions.js';
const operation=createLatestOperation();
const previewOperation=createLatestOperation();let preview=$state<Audio[]>([]),previewBusy=$state(false),added=$state<string|null>(null);let addedTimer:ReturnType<typeof setTimeout>;onDestroy(()=>{previewOperation.cancel();clearTimeout(addedTimer);});
$effect(()=>{const lo=Date.parse(from+'T00:00:00+08:00')/1000,hi=Date.parse(to+'T00:00:00+08:00')/1000+86400;void backend.generation;previewOperation.cancel();preview=[];previewBusy=false;if(!open||!from||!to||!(lo<hi))return;previewBusy=true;const timer=setTimeout(()=>void previewOperation.run(async(signal:AbortSignal)=>audiosInRange(lo,hi,signal),(audios:Audio[])=>{preview=audios;previewBusy=false;}).catch(()=>{previewBusy=false;}),180);return()=>{clearTimeout(timer);previewOperation.cancel();};});
function addOne(audio:Audio){prependTracks([{queueEntryId:crypto.randomUUID(),audio}]);added=audio.id;clearTimeout(addedTimer);addedTimer=setTimeout(()=>added=null,1200);}
let busy=$state(false),error=$state(''),result=$state<Audio[]>([]);let controller:AbortController|undefined;
function cancel(){controller?.abort();operation.cancel();busy=false;}onDestroy(cancel);
$effect(()=>{void from;void to;void backend.generation;void open;cancel();result=[];error='';});
async function generate(){const url=new URL(location.href);if(from)url.searchParams.set('from',from);else url.searchParams.delete('from');if(to)url.searchParams.set('to',to);else url.searchParams.delete('to');history.replaceState(history.state,'',url);cancel();const c=new AbortController();controller=c;busy=true;error='';try{if(!from||!to)throw Error('请选择完整日期范围');const lo=Date.parse(from+'T00:00:00+08:00')/1000,hi=Date.parse(to+'T00:00:00+08:00')/1000+86400;await operation.run(async(signal:AbortSignal)=>{const audios=await audiosInRange(lo,hi,signal);if(!audios.length)throw Error('范围内没有音频');return audios;},(audios:Audio[])=>{result=audios;const tracks:Track[]=audios.map(audio=>({queueEntryId:crypto.randomUUID(),audio}));prependTracks(tracks);});}catch(e){if(!c.signal.aborted)error=e instanceof Error?e.message:'生成失败';}finally{if(controller===c)busy=false;}}
</script>
<section class="card rounded-xl border bg-base-100 p-4"><div class="flex items-center justify-between"><h2 class="flex items-center gap-2 text-sm font-semibold"><ListMusic class="h-4 w-4"/> 按时间生成</h2><button class="rounded p-1 transition hover:bg-base-200" aria-label="收起" onclick={()=>open=false}><X class="h-4 w-4"/></button></div><div class="mt-3 flex flex-wrap items-center gap-2 text-xs"><input aria-label="开始日期" type="date" bind:value={from} class="rounded border border-base-300 bg-base-200 px-2 py-1 tabular-nums"/><span class="opacity-50">→</span><input aria-label="结束日期" type="date" bind:value={to} class="rounded border border-base-300 bg-base-200 px-2 py-1 tabular-nums"/><button class="flex items-center gap-1 rounded bg-accent px-2.5 py-1 text-accent-content transition hover:opacity-90" disabled={busy} onclick={generate}><Search class="h-3 w-3"/> 生成并插入队列</button>{#if busy}<button onclick={cancel}>取消</button>{/if}</div>{#if busy}<p role="status" class="mt-3 text-xs">正在按月加载，完成前不会修改队列…</p>{/if}{#if error}<p role="alert" class="mt-3 text-xs text-warning">{error}（原队列未修改）</p>{/if}<div class="mt-3 border-t border-base-300 pt-3 text-xs"><span class="rounded-full bg-accent/15 px-2 py-0.5 text-2xs tabular-nums opacity-80">{preview.length} 首 · {fmtDur(preview.reduce((n,a)=>n+(a.duration??0),0))}</span>{#if previewBusy}<p role="status" class="mt-2 text-2xs opacity-50">正在加载范围预览…</p>{:else if preview.length}<ol class="mt-2 max-h-64 space-y-0.5 overflow-y-auto">{#each preview.slice(0,20) as audio,i (audio.id)}<li><button class="group flex w-full items-center gap-2 rounded px-1 py-0.5 text-left text-xs transition hover:bg-base-200" aria-label={'加入队列：'+audio.title} onclick={()=>addOne(audio)}><span class="w-7 shrink-0 text-2xs tabular-nums opacity-50">{i+1}</span><span class="truncate">{audio.title}</span><span class="ml-auto shrink-0 text-2xs tabular-nums opacity-50">{fmtDur(audio.duration??0)}</span>{#if added===audio.id}<Check class="h-3 w-3 shrink-0 text-accent"/>{:else}<Plus class="h-3 w-3 shrink-0 opacity-40"/>{/if}</button></li>{/each}{#if preview.length>20}<li class="px-1 py-0.5 text-2xs opacity-50">…其余 {preview.length-20} 首</li>{/if}</ol>{:else}<p class="mt-2 px-1 text-2xs opacity-50">范围内没有切片</p>{/if}</div></section>
